state.examples:
Three solved examples: three other designs, each with the result of the simulator compiler in `tool`. The question is about the design in `rtl`, not about these examples.

Example 1. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
	clk,
	ld,
	rst,
	d,
	q
);
	// synthesis attribute keep_hierarchy dffl_18 "true";
	input clk;
	input ld;
	input rst;
	input [17:0] d;
	output [17:0] q;
	reg [17:0] q;

	always @(posedge clk) begin
		if (rst == 1'b0) begin
			q <= 18'b0;
		end else if (ld == 1'b1) begin
			q <= d;
		end
	end
endmodule
Correct answer: yes. vlog reports no error.

Example 2. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
	clk,
	ld,
	rst,
	d,
	q
);
	// synthesis attribute keep_hierarchy dffl_18 "true";
	input clk;
	input ld;
	input rst;
	input [17:0] d;
	output [17:0] q;
	reg [17:0] q;

	always @(posedge clk) begin
		if (rst == 1'b0) begin
			q <= 18'b0;
		end else if (ld == 1'b1) begin
			q <= d_x;
		end
	end
endmodule
Correct answer: no. vlog reports at least one error. The first error: ** Error: rtl/metrex_05095.v(21): (vlog-2730) Undefined variable: 'd_x'.

Example 3. Top module accu. RTL:
// ---- file: Prob001_accu.sv ----
module accu(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [1:0] counter;
reg [9:0] sum;
reg [9:0] data_out_reg;
reg valid_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 2'b00;
        sum <= 10'b0;
        data_out_reg <= 10'b0;
        valid_out_reg <= 1'b0;
    end else begin
        if (valid_in) begin
            if (counter == 2'b11) begin
                counter <= 2'b00;
                sum <= 10'b0;
                data_out_reg <= sum;
                valid_out_reg <= 1'b1;
            end else begin
                sum <= sum + data_in;
                counter <= counter + 1'b1;
                valid_out_reg <= 1'b0;
            end
        end else begin
            valid_out_reg <= 1'b0;
        end
    end
end

always @(posedge clk) begin
    data_out <= data_out_reg;
    valid_out <= valid_out_reg;
end

endmodule
Correct answer: no. vlog reports at least one error. The first error: ** Error: rtl/Prob001_accu.sv(40): (vlog-2110) Illegal reference to net "data_out".

